// Experience.js
import React from 'react';
import { useSpring, animated, config } from 'react-spring';
import ExperienceItem from './ExperienceItem'; // <-- Import the child component

const Experience = () => {
  const experiences = [
    {
      title: 'Faculty Leader(Engineering)',
      company: 'University of Alberta',
      period: 'March 2024 – Present',
      description:
        'Delivered orientation sessions and conducted workshops for first-year students.',
    },
    {
      title: 'Supporting Students Affected by Conflict',
      company: 'University of Alberta',
      period: 'July 2023 – Present',
      description:
        'Played a vital role in ensuring newcomer students from asylum countries felt supported and welcomed as they transitioned into life on campus.',
    },
 
  ];

  // Fade-in animation for the entire Experience section
  const fadeIn = useSpring({
    opacity: 1,
    from: { opacity: 0 },
    config: config.molasses,
  });

  return (
    <animated.div style={fadeIn} className="experience-section">
      <h2>Experience</h2>

      {experiences.map((exp, index) => (
        // Render a child component for each experience
        <ExperienceItem key={index} exp={exp} index={index} />
      ))}
    </animated.div>
  );
};

export default Experience;